import React from 'react';
import { InfoTooltip } from '../common/InfoTooltip';

// Keep explanations next to their domain. Calculations follow journalMath and the
// backtest engine; these describe recorded evidence, not live broker guarantees.
export const JOURNAL_HELP: Record<string, string> = {
  'Backtest Dashboard': 'Compare saved tests, practice results and recorded journal trades without rerunning a test. Every source keeps its own curve and balance. Bubble comparison defaults to win rate, profit factor, trade-count size and result-type color. Compare playbooks, markets or instruments, then select a bubble to inspect its exact trades. Focus a result for headline metrics and the calendar. Filters use closed-result dates in the selected timezone; untimed journal records retain their recorded UTC day.',
  'Performance comparison': 'Four dimensions: horizontal position, vertical position, bubble size and color. Defaults are win rate, profit factor, trade count and result type. Customize chart changes these metrics. Each bubble contains one group within one selected result; overlapping saved tests are kept separate. Test from journal means a sample simulation started with selected journal records; Recorded journal shows the actual benchmark. Infinity has a separate band for profits without losses. Missing risk excludes R metrics only. Select a bubble or use Explore a bubble, then View trades.',
  'Strategy Lab': 'Choose saved playbooks or journal trades, review the prefilled test copy, then run a sample simulation or practice manually. Journal trades remain a separate benchmark. Suggested technical rules require your choice; written instructions remain manual guidance. Completed tests and your draft are saved in this browser.',
  'Trading Journal': 'Bring your trades, setup rules and reviews together. Start with Overview for a summary, inspect individual entries in Trade Log, look for patterns in Insights, and use Playbook, Backtest and AI Coach to plan experiments.\n\nRecords and edits in this build are saved in this browser. Currency, account, date and journal filters determine the evidence shown; clearing browser storage can remove locally saved work.',
  'Overview': 'Your summary of the current journal scope: trading results, risk, discipline, review tasks and daily activity. Change the filters to compare the same group of trades across cards and charts.\n\nGross and net change the trading result basis. Cashback and Points are separate reward estimates. Select a chart day or an entry to inspect the records behind a number.',
  'Trade Log': 'Inspect and organize the trades inside your journal filters. Search by instrument, playbook, broker or tag; sort columns, group rows and choose which columns are visible.\n\nSelect a trade to review its costs, risk and execution evidence. Row checkboxes enable bulk actions. Planned, open and unknown-cost records remain visible but do not contribute to eligible closed net totals.',
  'Insights': 'Compare results by strategy, plan adherence, emotions, mistakes and trading time. Day & Time adds distributions, a cross-analysis matrix and a detailed breakdown that can open its source trades.\n\nJournal filters apply first; report filters can narrow the data further. Use counts alongside averages: a pattern in a small historical sample is a question to investigate, rather than a prediction.',
  'Playbook': 'Write a repeatable setup: markets, session, entry conditions, invalidation, exits and risk limits. Link journal trades to its name to track execution and results.\n\nOpen a playbook for analytics, scenario hypotheses, execution checks, replays and review history. Written rules support your review; only supported rules transferred into Backtest settings are simulated.',
  'Backtest': 'Compare playbooks on past prices, try a What-if rule on recorded trades, or practice with future candles hidden. Saved runs let you return to settings and results.\n\nCheck the data-source label and execution assumptions on each screen. Sample or generated candles demonstrate the workflow and cannot establish live profitability. A simulation is separate from your actual journal results.',
  'AI Coach': 'Explore editable experiments based on your trading evidence and a strategy library. Choose a trade for scenario comparisons, or expand playbook experiments to inspect historical patterns.\n\nThis Beta uses local, transparent rules in your browser. Earlier entry dates select ideas; later dates provide a chronological check. Library alternatives are untested until you run them, and saving an experiment creates a draft.',
  'Import or link trades': 'Import a CSV statement into this browser. Supply the account identity, currency, source time offset and P&L basis, then inspect the preview and any rejected rows before importing.\n\nThe Link account screen describes broker connection availability; this build does not automatically synchronize broker history. Importing records does not place orders.',
  'Account currency': 'Keep monetary results in the selected account currency. Entries in other currencies are excluded and no exchange-rate conversion is applied. Choose a currency with saved records to populate the view.',
  'Account': 'Choose one recorded account identity or combine accounts in the selected currency. This scope applies before the journal date and category filters; it does not connect to or change a broker account.',
  'Date range': 'Both start and end dates are included. Journal scope uses the recorded entry date in UTC, even when a trade closes later. Presets and custom dates change which records feed the journal views.',
  'Choose your date range': 'Select a preset or enter a custom inclusive start and end date, then apply the range. Dates filter recorded UTC entry days; changing the calendar month alone is not the same as applying a new journal range.',
  'Market type': 'Include or exclude recorded asset classes such as Forex, Crypto, Stocks, Indices and Commodity. In Backtest, the market selection controls the available supported symbols; inspect the contract and size units before testing.',
  'Net outcome': 'Classifies eligible closed trades after recorded costs: positive is a win, negative is a loss, and an absolute result up to 0.005 is breakeven. Not realized / unknown also includes trades whose net result cannot be calculated.',
  'Trading status': 'Planned means an idea awaiting execution; open means the position is not fully closed; closed means a reported realized result. This is separate from the review state, which tracks whether your journal notes are complete.',
  'Broker': 'The broker assigned to a journal record. Filter by broker to compare the same account currency across venues; unassigned records can be included separately. Assignment alone does not establish a live connection.',
  'Overview show': 'Trading shows the chosen gross or net trading result. + Cashback adds the stored or estimated USD cashback only to USD trades. Points shows estimated base rewards instead of money; these are not trading returns.',
  'Overview basis': 'Gross uses the reported realized P&L before costs. Net subtracts the recorded total costs from gross. Open and planned trades are excluded; net also excludes records with unknown costs rather than assuming those costs are zero.',
  'Net P&L': 'For eligible closed trades, net P&L equals reported gross P&L minus recorded costs. Unknown costs and unreported results are excluded, not treated as zero. Cashback and Points are separate unless the Overview display explicitly adds cashback.',
  'Gross P&L': 'Reported realized trading P&L before recorded fees, commissions and swaps. Open and planned positions are excluded. Compare with net P&L to see how known trading costs affect the result.',
  'Win rate': 'Winning trades divided by all eligible closed trades, including breakeven, multiplied by 100. The journal uses the selected result basis; Trade Log and net reports use results after costs.\n\nA dash means there are no eligible results. A high win rate does not describe the size of losses or prove that a strategy is profitable.',
  'Profit factor': 'Sum of positive eligible results divided by the absolute sum of negative eligible results. A value above 1 means recorded gains exceeded recorded losses on this scope.\n\nInfinity means there are positive results and no negative results; a dash means the ratio is unavailable. The rolling playbook chart caps the displayed value at 5.',
  'Average R': 'Average realized result measured in units of initial monetary risk. For eligible net trades, R = net P&L ÷ positive initial risk; an explicitly recorded R value is used when initial risk is unavailable.\n\nOnly trades with known R contribute. For example, +2R means twice the initial risk was earned; −1R means an amount equal to that risk was lost. Journal R remains net even in the gross Overview view.',
  'Plan followed': 'Share of trades with an explicit Yes for plan adherence, out of all trades with an explicit Yes or No in the scope. Unanswered reviews are excluded. This measures your recorded process, independently of whether a trade won.',
  'Journal streak': 'Consecutive recorded days ending at the latest saved journal date, across all saved entries. It can include older dates and does not need to reach today. Several trades on the same day count as one day; this is recording activity, rather than a winning streak.',
  'Average win / loss': 'Average positive result and average negative result are calculated separately. The payoff ratio divides average win by the absolute average loss and needs both groups. Breakeven trades contribute to neither group.',
  'Comm. & Fees': 'Recorded trading costs such as commissions, fees and swaps. Net P&L subtracts this total once from gross. Unknown costs are not evidence of free trading; supply them in the trade review to make a net result eligible.',
  'Cashback (est. USD)': 'Uses stored cashback when available, otherwise estimates the assigned broker’s per-lot rebate for supported lot-based closed trades. It stays in USD and is separate from trading P&L. Actual eligibility and payment can differ from an estimate.',
  'Points': 'Estimated base MarketSyde reward points for supported closed lot-based trades, calculated from recorded size and market type before level boosters. Points are not cash, trading profit or confirmation that rewards have been credited.',
  'Review queue': 'Trades in the current scope whose review is not Complete, including reopened reviews. Missing costs, emotions, plan adherence, execution rating or lessons can leave evidence incomplete. Open an entry to save a draft or complete its review.',
  'Recent entries': 'Recent journal records inside the selected scope. Select an entry to inspect and review it, or select a calendar day for its daily workspace. The replay control opens the separate replay view.',
  'Cumulative result': 'Running total of the selected result within the filtered entry dates, starting from zero for this view. Broker lines use the same selection; reward display modes follow the Overview controls.\n\nHover or focus a point for values, switch to Table for rows, or select a day for its review. This is a journal result curve, not a broker account-equity history.',
  'Calendar': 'Daily results grouped by recorded UTC entry date inside the current journal scope. Month navigation changes the calendar view; selecting a day opens linked trades, the result curve and a daily reflection.',
  'Discipline': 'A recorded-process score: plan adherence carries 50%, checklist completion 30%, and mistake-free trades 20%. Only sufficiently answered reviews contribute. With no checklist items, the checklist component is treated as complete.\n\nThe score is a review aid, not a measure of profit or a psychological diagnosis. Unanswered trades are excluded rather than credited as mistake-free.',
  'Personal rules': 'Checks recorded trades against your house limits. Daily trade counts and continuing after consecutive losses can be checked when the required evidence exists. Missing risk, equity or timing evidence leaves a check Unknown.\n\nNo known breaches does not establish that every rule was followed. Edit limits in Playbook and use the linked records to investigate a flagged day.',
  'Tilt monitor': 'Looks at the latest five records for repeated losses, recorded negative emotions and off-plan behavior. It is a prompt to pause and review your process, based on journal answers rather than a live assessment of your mental state.',
  'What your journal says': 'Compares average eligible net results for explicitly on-plan and off-plan trades in this scope. Unanswered plan adherence is omitted. Differences describe this history and do not establish that one behavior caused the outcome.',
  'Plan adherence': 'Record whether you followed the plan that existed when you entered, independently of the final P&L. Yes and No feed process comparisons; leave Unknown when you do not have enough evidence to answer.',
  'By strategy': 'Groups eligible net results by the playbook name recorded on each trade. Each row shows count, win rate and total net P&L in the journal scope. Compare sample size, risk and market conditions before drawing conclusions.',
  'P&L by weekday': 'Eligible closed net results grouped by the weekday of the recorded entry date. Bar size represents the magnitude and color indicates gain or loss. The Overview uses UTC; Day & Time can use your chosen report timezone.',
  'Emotion vs. result': 'Groups eligible net results by recorded emotion and compares average outcomes. Missing answers limit coverage. Treat differences as descriptive observations for review, rather than a diagnosis or proof of causation.',
  'Most common mistakes': 'Counts the mistake tags recorded on trades in this scope. One trade can carry several tags. An empty unreviewed mistake list is not proof that an execution was mistake-free.',
  'Date & Time': 'The recorded entry timestamp, displayed in UTC in Trade Log. If no entry time was supplied, only the recorded date is shown. Sorting by time uses the available entry timestamp or that day’s start.',
  'Instrument': 'The symbol recorded on the trade. A journal symbol may map to a supported backtest contract; check any alias, contract multiplier and quantity-unit differences before comparing simulated money results.',
  'Review': 'Tracks journal completion independently of trading status: Needs review, In progress or Complete. Open the entry to record evidence, save a draft or mark it complete once required answers are present.',
  'Side': 'Long / Buy seeks a gain as price rises; Short / Sell seeks a gain as price falls. The side alone does not describe position size, risk, leverage or the quality of the entry.',
  'Size': 'Recorded position quantity in its source units, such as lots, shares, coins or contracts. Quantities from different units are not interchangeable. Review contract valuation before using a journal quantity in a simulated position.',
  'Entry': 'Recorded entry price. Partial executions can be documented separately in the execution ledger; a single summary price does not by itself reconstruct every fill or its timing.',
  'Exit': 'Recorded exit price for the position. An absent exit may indicate an open trade or missing evidence; realized P&L and costs are still required for eligible closed net calculations.',
  'Execution Tags': 'Your descriptive labels for execution patterns, setups or behaviors. Search and group using tags to inspect comparable trades. Bulk tagging updates only selected records; tags themselves do not change the reported P&L.',
  'Outcome': 'Win, loss or breakeven for eligible closed net results. Open/planned trades and missing-cost results do not have a known realized net classification. Trading status and review completion are tracked separately.',
  'Group': 'Organize filtered rows by day, week, instrument, broker, playbook, direction, outcome or trading status. Group totals use eligible results. Grouping changes presentation and does not change saved trades.',
  'Columns': 'Choose which fields appear in the table. Hiding a column changes the display only. Use the information icons beside column headings to check units, eligibility and how each value is calculated.',
  'Trade filters': 'Trade Log adds search, review, outcome, trading-status, market and broker filters inside the journal scope. The KPI strip and totals follow the filtered rows. A linked evidence selection can temporarily show its exact source trades.',
  'Bulk actions': 'Use row checkboxes to select trades, then tag them, change their broker assignment, export them or use an available analysis action. Select all applies to the current page. Inspect the selected count before confirming deletion.',
  'Timezone': 'Day & Time groups entry timestamps into your selected report timezone and applies daylight saving where supported. Changing this can move a trade into another day or hour bucket; it does not rewrite saved timestamps or the UTC journal scope.',
  'Day & Time': 'Explore when trades were entered and how long they were held. Switch between day, month, time and duration buckets; inspect a distribution or matrix cell to open the contributing records.\n\nOnly eligible closed net trades feed realized metrics. Session, timezone, market, playbook and subrange controls can narrow the report beyond the journal filters.',
  'Session filter': 'Include or exclude the report’s trading-session windows. The timezone control changes displayed clock times and date buckets; session windows follow their defined hours. Trades without usable timing cannot establish a precise session pattern.',
  'Benchmark vs prev period': 'Compare the selected 30- or 90-day report window with the immediately preceding equal-length period available in the journal scope. Counts may differ. Choose a finite subrange to enable the comparison; the entire scope has no preceding-period benchmark.',
  'Cross analysis matrix': 'Compare two grouping dimensions, such as playbook versus session or symbol versus weekday. Each cell summarizes its contributing eligible trades for the selected metric. Inspect the cell’s count and drill into its records before interpreting an extreme value.',
  'Detailed session & time breakdown': 'Tabular view of the selected grouping, with realized net results and sample counts. Sort or inspect rows to trace a summary back to the trades behind it. Report-level filters remain active when you drill down.',
  'Distribution': 'Groups eligible closed net trades by day, month, entry-time interval or holding duration. Choose the measure you want to inspect and select a bucket for its source records. A missing or very small bucket is limited evidence.',
  'Open positions & unrealized P&L': 'Shows recorded open-position information separately from realized closed results. Values depend on the latest journal evidence; this screen does not fetch live broker marks. Unknown P&L stays unknown.',
  'Your setups, rules and edge': 'Select a playbook to review its recorded results and execution rules, or create a new setup. Grade, status, markets and sessions help organize the library; analytics use trades linked to the recorded playbook name.',
  'Set up a strategy': 'Explore suggested setup recipes or define your own playbook. Inspect and edit the imported markets, rules, timeframe, risk and exits before testing. A suggested recipe has no measured edge merely because it appears in the library.',
  'Playbook editor': 'Define the setup in terms you can check consistently. Name connects the playbook to journal trades; execution rules and risk limits support review. Save changes when ready. A name already used by trades is locked to protect those links.',
  'Name': 'A clear, unique playbook name links trades to this setup. Once journal entries use that name, editing it is locked so existing history keeps the correct association.',
  'Style': 'Describe the setup family, such as trend following, momentum or mean reversion. This is an organizing label; the concrete entry and exit rules define the behavior to review or test.',
  'Grade': 'Your chosen quality label for this playbook. Recorded results may suggest a grade, but you control the saved value. Check the sample and grade criteria rather than treating a letter as a guarantee of future performance.',
  'Status': 'Draft is an unfinished setup; Active is a setup you currently use; Testing is being evaluated; Archived keeps its history while removing it from active setup choices. Use the filters beside the playbook list to browse each state. This library status is separate from an individual trade’s open/closed status.',
  'Markets': 'Asset classes the playbook is intended to cover. Select only markets for which the setup and contract assumptions make sense. These selections help organize compatible scenarios and testing choices.',
  'Session window': 'Optional UTC hours during which this playbook is intended to enter trades. Check the from/to hours and label; recorded execution checks use this setup context. A written session must be supported in test settings to be enforced in simulation.',
  'Min reward:risk (1:x)': 'The planned reward target for each unit of initial risk; 2 means a target of 2R for 1R risk. It is a planning benchmark and a target-hit threshold in analytics, not the result every trade will realize.',
  'Risk per trade (% of account)': 'The playbook’s intended percentage risk for a trade. When omitted, the house limit supplies context. This records your rule and does not size or send a real broker order.',
  'Max trades per day': 'Your intended upper number of entries per recorded day. House rules and playbook rules can have separate limits. Review monitor evidence and automated test settings to see which limit is being checked.',
  'Do not trade when (one per line)': 'Write one skip condition on each line, such as a news event or an invalid market structure. These are manual review conditions unless a corresponding supported backtest filter is explicitly configured.',
  'Thesis': 'Explain why the setup should work, the conditions it needs and where it is likely to fail. A specific thesis makes later review more useful and helps distinguish a repeatable idea from a single outcome.',
  'Execution rules': 'Give each rule a short title and an observable condition. Review records can capture met, broken or unknown evidence. Written prose is not automatically converted into executable strategy logic.',
  'Entry trigger': 'Describe the event that confirms an entry, including price behavior, timing or indicator conditions where relevant. A clear trigger helps you compare executions consistently; supported automated conditions are configured separately.',
  'Stop / invalidation': 'Describe what would invalidate the trade and where the initial stop belongs. Keep the original risk evidence so later stop adjustments do not silently change how realized R is interpreted.',
  'Profit taking': 'Describe how to exit profitable trades: target, partial exits, trailing management or time rules. The written plan is a review reference; automated tests apply the exit settings shown on their setup screen.',
  'Analytics': 'Track the linked playbook’s win rate, profit factor, payoff and target-hit behavior. Rolling results use up to ten eligible trades at a time; the comparison and R distribution use their labeled cohorts. Small samples can move sharply.',
  'Setup rules: what must be true': 'The conditions written in this playbook before taking a setup. Check them against evidence rather than marking them met based on the outcome. Missing evidence remains unknown.',
  'Scenarios: your trade hypotheses': 'Draft a specific market idea with a symbol, direction, trigger, entry, stop, target and validity date. Scenario status tracks the hypothesis lifecycle; it does not place or manage a broker order.',
  'Hypothesis': 'Write the market behavior you expect and the reason for it. Make the idea specific enough that later evidence could confirm or invalidate it.',
  'Trigger: what confirms it': 'State the observable event required before acting on this scenario. A trigger is distinct from the broader thesis and from the price level that would invalidate it.',
  'Valid until': 'The scenario’s expiry date. Use it to distinguish a still-relevant hypothesis from an outdated idea; the saved date is an organizational record rather than an exchange order-expiry instruction.',
  'Recent executions': 'Recent journal entries linked to this playbook inside the selected scope. Open an execution to inspect its original context, costs, notes and review evidence.',
  'Your execution replays': 'Review recorded or attached execution evidence for this playbook. A replay is a learning view and may have limited price coverage; check its data-source and availability information.',
  'Best executions': 'Selected historical executions that illustrate this playbook. Open their reviews and replays to inspect the process as well as the result; a highlighted winner is not representative of every trade.',
  'Review log': 'Saved review notes for this playbook, so you can track lessons and changes over time. Keep observations specific and compare them against subsequent execution evidence.',
  'House rules': 'Personal limits and checklist items used across the journal. They provide defaults and review context; this local app does not enforce limits on a broker account or prevent real trading.',
  'Trading rules': 'Set personal limits for risk per trade, daily loss, entries per day and consecutive losses. The monitors flag what can be established from recorded evidence; unsupported checks remain Unknown.',
  'Pre-trade checklist': 'Record the checks you intended to complete before entering. Checked items are explicit positive evidence. Unchecked legacy items may be unanswered, so they are not automatically proven rule violations.',
  'Daily review': 'Inspect one recorded UTC entry day, its linked trades and a trade-by-trade net curve. Save a daily reflection and review progress; the day’s content follows the available journal evidence.',
  'Trade-by-trade net result curve': 'Running sum of eligible closed net results for the day in recorded order. Unknown costs or unreported realized results are excluded. Select a point to inspect the trade behind a change.',
  'Daily reflection': 'Capture what happened, what you learned and the process you want to repeat or change. Reflections are saved locally and complement individual trade reviews; they do not alter reported trading results.',
  'Daily progress': 'Review completion across the trades linked to this day. Completion reflects answered journal fields and is separate from profit, trading status and plan adherence.',
  'Psychology and review': 'Record emotions before and after, plan adherence, an execution rating and a lesson. Honest answers help process analysis; missing answers should stay unknown instead of becoming automatic positives.',
  'Reported gross P&L': 'The realized trading result before fees, commissions and swaps, in the account currency. If a statement reports net P&L, use its import basis so costs are not subtracted twice. Closed net metrics also require known total costs.',
  'Total costs (fees, commissions, swaps)': 'Enter the total recorded costs as zero or a positive amount in account currency. Blank means unknown. Net P&L subtracts this amount from reported gross P&L; do not enter a net result as gross and then subtract the same costs again.',
  'Initial monetary risk': 'The positive account-currency amount intended to be lost at the original stop. Known initial risk lets the journal calculate realized net R. Leave it unknown when you cannot establish it from recorded evidence.',
  'Margin at entry': 'Recorded margin used for this position at entry, in account currency. This supports margin/equity comparisons when equity is also known; it is not the maximum possible loss or live liquidation information.',
  'Equity at entry': 'Recorded account equity when the trade opened. A positive known value supports risk and account-return percentages. It is not inferred from the result, current balance or unrelated trades.',
  'Execution rating': 'Your process-quality assessment of the execution. Rate the decisions and rule adherence rather than rewarding a profitable accident. A missing rating keeps the required review evidence incomplete.',
  'Lesson / linked notes': 'Record the main lesson and useful context or references. A concrete observation is more useful than an outcome-only judgment; this field is required to mark a review Complete.',
  'Rule evidence': 'Record each setup rule as met, broken or unknown using the evidence available. Saved rule context helps preserve what you reviewed even if the playbook later changes. Unknown is distinct from failure.',
  'Execution ledger and risk history': 'Document individual entry/exit fills with UTC timestamps, quantities, prices and known fees, plus changes to risk evidence. This preserves execution detail; adding evidence does not send an order to a broker.',
  'Fill UTC time': 'The actual timestamp of this partial execution in UTC. Use the original source record where possible; accurate order matters for reconstructing entries and exits.',
  'Fill side': 'Choose Entry when adding quantity to the position and Exit when reducing it. Use the execution ledger to document partial fills; the remaining quantity is derived from entries less exits.',
  'Attach chart image (local, up to 3 MB)': 'Add a chart screenshot as local review evidence, subject to the size limit. It is stored with this browser’s journal data and is not a live price feed.',
  'Account identity (required)': 'Use a consistent identifier for the statement’s trading account. It separates account history and supports duplicate detection across repeated imports. Reuse the same identity when importing more records from the same account.',
  'Source UTC offset': 'The fixed UTC offset used by the statement timestamps. The importer uses it to normalize times; verify the source broker’s offset for the statement period, especially when daylight saving changed.',
  'Statement P&L basis': 'Choose whether the statement’s P&L field is Gross or Net. The importer uses this with supplied costs to preserve the correct gross and net amounts. Verify the preview so fees are not counted twice.',
  'Open risk / equity': 'Known initial monetary risk divided by recorded equity for the open-position snapshot. Missing risk or equity limits coverage. This uses journal evidence and does not estimate live stop execution or liquidation risk.',
  'Margin used / equity': 'Recorded margin as a percentage of recorded equity in the labeled snapshot. This differs from broker margin level, which reverses that ratio. Unknown inputs are not guessed.',
  'Current portfolio equity (USD)': 'The equity snapshot available from recorded open-position evidence. Inspect data coverage and account scope; this is not a continuously updated broker balance.',
  'Source size': 'Combined recorded quantities only when their quantity units agree. Mixed units cannot be meaningfully summed, so the view shows Mixed / unknown rather than adding lots, shares and contracts together.',
  'Portfolio notional': 'The full market exposure would require reliable units, prices and contract multipliers. When those prerequisites are not recorded, notional remains unavailable rather than being inferred from margin or quantity alone.',
  'Your goal': 'Choose the process or performance question you want the coach to explore. The goal changes which eligible experiments are considered; it does not guarantee improvement or change saved trades.',
  'Build around': 'Choose a specific active playbook or let the coach look across the available library. Account, currency and journal filters still constrain the evidence used to build a suggestion.',
  'Playbook evidence scope': 'All dates retains the current account and category filters but allows earlier history. Current journal date range additionally limits the dates. Inspect the eligible-close count to understand what supports each scenario.',
  'What your history suggests': 'Ideas are selected using the earlier 70% of unique entry dates and checked on later dates. Strategy ranking needs at least five earlier closes; behavior comparisons need at least three observed trades per side. Missing answers do not count as positive evidence.',
  'Compare the evidence': 'Compares the later-period recorded baseline with historical subsets retained by each scenario rule. Counts and position sizes may differ. This is an observed cohort comparison, not a simulated alternative return; library recipes have no measured result here.',
  'A few paths to test': 'Each card explains the proposed change, source evidence and suggested next step. Save draft preserves a new editable experiment; Save & practice opens replay, while Save & test/compare opens test settings for inspection.',
  'Setup rules & source evidence': 'Inspect the written rules and linked trades behind the coach’s suggestion. Behavior checklists are manual; an automated test only applies its supported market rules. Check the setup before running an experiment.',
  'How this coach builds scenarios': 'This local rules-based Beta analyzes eligible closed net journal evidence. It separates earlier selection dates from later checking dates and excludes open, unknown-result, future and other-currency records. Expand this section for cohort thresholds and fallback-date details.',
  'Your playbooks: tested vs live': 'Live values come from recorded journal trades linked to a playbook; Tested values come from the saved expected backtest for that playbook. Inspect instruments, periods, costs and sample counts before comparing them.',
  'Backtest vs live': 'Compares your eligible journal sample with the saved expected statistics for the playbook. A health flag is a review prompt that depends on sample size and assumptions, rather than proof that a strategy has stopped working.',
  'Strategy health': 'Summarizes the gap between linked journal execution and saved backtest expectations. Missing expected data or too little live evidence can leave health unresolved. Open Backtest to inspect the underlying assumptions.',
  'Test runs this month': 'Tracks automated test usage against the current plan allowance and any prepaid extra runs. Inspect the displayed credit price before purchasing an extra run. What-if and practice have their own free workflows.',
  'Practice': 'Replay historical or sample candles while future bars are hidden. Use the order ticket to rehearse entries and exits, then inspect the session summary. Practice results and Points are separate from real trades and broker balances.',
  'Recent runs': 'Recently saved backtests from this browser. Open a run to revisit its results and settings; unsaved results are not automatically part of this history.',
  'Saved runs': 'Review, reopen and compare locally saved backtest results. Compare consistent settings and data sources; naming a run helps preserve which question it tested. Saving a run does not update actual journal trades.',
  'Compare runs': 'Select saved runs to compare results and equity curves. Different dates, instruments, risk, costs and trade counts can explain apparent differences, so inspect those assumptions alongside the summary metrics.',
  'Equity curves': 'Simulated account-value paths for the selected saved runs. Each curve follows that run’s sizing, costs and starting balance; it is not your broker’s actual equity history.',
  'Scenario comparison': 'Compare tested strategy variations using their labeled data and settings. Check counts, net return, drawdown and changed assumptions together. The best observed variation can reflect selection bias rather than a durable advantage.',
  'Playbook comparison': 'Tests selected playbooks with shared market, dates, risk and costs while retaining their own strategy rules, timeframe and session. Inspect the differences before choosing a setup for further testing.',
  'Robustness checks': 'Examines how the simulated result changes under the displayed stress or validation checks. Consistency across checks is useful evidence, but the result still depends on data quality, execution assumptions and sample size.',
  'When it works': 'Breaks simulated trades down by the labeled conditions to reveal where this run performed differently. Use counts alongside averages and confirm promising patterns on additional data before changing a setup.',
  'Money, risk and costs': 'Set the simulated starting account, position-sizing method, loss limits and execution costs. These assumptions can materially change results; broker-derived defaults and house limits remain editable estimates.',
  'Starting balance': 'Initial simulated account value in the selected currency. Percentage sizing grows or shrinks with the simulated balance. This value does not connect to or fund a real account.',
  'Weekdays': 'Allow new simulated entries only on selected weekdays. This filter is shared across compared playbooks; it does not remove the need to inspect each playbook’s session window.',
  'Use costs from my broker': 'Prefills estimated commission, spread and slippage from available broker metadata and instrument defaults. Verify each value against the intended account type; these are not guaranteed historical or live execution costs.',
  'Playbooks': 'Select one or more non-archived setups to test. Each keeps its transferred strategy rules, timeframe and session, while the comparison shares market, dates, sizing and costs. Inspect each selected setup before running.',
  'Fill model': 'Controls how the simulator resolves entry/exit fills and ambiguous intrabar price paths. A candle does not reveal every tick; the chosen assumption can change stop/target order and simulated performance.',
  'Max drawdown': 'Largest simulated peak-to-trough decline under the run’s equity and sizing assumptions. Inspect whether the result is shown in money or percent. It describes this path and is not a maximum loss guarantee.',
  'What-if scenario lab': 'Apply a selected alternative rule to recorded journal evidence and compare the supported changes against the actual baseline. Review coverage and execution assumptions; missing price-path evidence limits which exits can be reconstructed.',
  'Scenario parameter': 'Choose the rule change and its value for this What-if study. Change one assumption at a time when you want to understand its effect, and inspect how many recorded trades support the comparison.',
  'Actual vs what-if': 'Actual is the recorded eligible journal baseline; What-if is the outcome supported by the selected rule and available evidence. Retained-cohort filters and price-based simulations answer different questions, so inspect the model and coverage labels.',
  'Candles & scenario comparison': 'Compare the selected source trade and scenario on the available candle window. The chart and equity scope can show different subsets; read the data source and coverage before treating a hypothetical path as historical evidence.',
  'Parameter optimization': 'Ranks candidate parameter values using the earlier training period. Inspect the later-period check separately. Searching many values can fit historical noise; the highest observed training result is not independent validation.',
  'Saved What-if runs': 'Locally saved scenario studies preserve their selected rules, evidence and results. Open a study to inspect its assumptions or compare it with the actual recorded baseline.',
  'Practice source': 'Choose the instrument and candle source for replay. A linked journal trade provides context; the displayed candles may be a separate sample. Check coverage before comparing simulated results with the recorded execution.',
  'Order ticket': 'Configure a simulated entry, stop, target and risk on the visible replay bars. Order type and sizing determine how the practice engine handles the next price action. This ticket operates inside practice and sends no broker order.',
  'Position': 'The currently simulated replay position, including quantity, entry, stop, target and reported practice P&L. Future candles are revealed through playback; position values follow the replay’s contract and cost assumptions.',
  'Practice performance': 'Results of simulated trades in this replay session. Evaluate execution and rule adherence alongside P&L; the session does not modify your actual recorded trading returns.',
  'Trade history setup': 'Original setup context from the chosen journal entry. Copying recorded prices or size into a simulation requires compatible instruments, units, valuation and costs; review missing evidence before transferring values.',
  'Playback': 'Reveal candles progressively, step one bar at a time or play at the selected speed. Moving the timeline changes the visible historical window; the data-source label tells you whether the feed is sample or historical.',
  'Position size & setup monitor': 'Shows how demo equity, sizing and the selected playbook/scenario interact. Check units and risk budget before interpreting money results. Demo valuation is an assumption rather than a live broker contract specification.',
  'Test a strategy hypothesis': 'Try an editable direction, stop distance and reward target on the replay candle sample. Inspect the execution ledger and costs to understand the generated hypothetical result.',
  'Find a setup worth testing': 'Compare supported candidate setups under the displayed evidence and scoring criteria. A suggested candidate is an editable starting point for testing; inspect its changed rules and trade-offs before adopting it.',
  '1. Choose trades to analyze': 'Select the period, market and instrument for the source-trade cohort. These controls determine which recorded examples can support scenario comparisons; inspect eligible counts and missing evidence.',
  '2. Pick several alternative scenarios': 'Choose the alternative setup or management assumptions to compare against the same source trades. Read each scenario’s change and coverage so the comparison answers a clear question.',
  '3. One trade vs selected scenarios': 'Inspect one recorded trade alongside selected scenario alternatives. Open the trade-by-trade table for traceability and distinguish observed results from hypothetical price-path calculations.',
  'Per page': 'Choose how many filtered trades appear on each table page. Page size affects display and the Select all on this page action; summary totals still describe the full filtered set.',
  'Scenario status': 'Watching is an idea awaiting its trigger; Triggered records that the setup occurred; Invalidated records that the idea failed; Closed marks a finished scenario. This is your saved hypothesis state and does not send broker instructions.',
  'Setup': 'Review the playbook thesis, intended markets, entry trigger, invalidation and profit-taking plan. These describe the setup you mean to execute; later steps capture rule checks and execution evidence.',
  'Rules': 'Inspect the setup conditions and situations to avoid. Mark rules from evidence rather than from the trade outcome. Written instructions are enforced in an automated test only when they map to its supported settings.',
  'Checklist': 'Work through the playbook and house checks before an entry. Save explicit answers so later reviews can distinguish a followed process from missing evidence.',
  'Scenarios': 'Write and track specific trade hypotheses linked to this setup. Inspect direction, trigger, planned prices and expiry before using a scenario for practice or comparison.',
  'Execution': 'Inspect trades and replays linked to this playbook. Compare the intended process with recorded fills, costs and risk, then open an entry to supply missing evidence.',
  'Playbook review': 'Record lessons and decisions about this setup after examining its execution history. Saved notes preserve your reasoning for continuing, testing or changing a rule.',
  'Market, dates, risk and costs': 'Choose a supported instrument and an inclusive test period, then set starting balance, position sizing and execution costs. Selected playbooks share these assumptions while retaining their own timeframe and session.',
  'What to test': 'Choose the playbooks and inspect the executable entry, filter, stop and exit conditions transferred from each one. Written notes remain available for context; only the displayed supported rules run in the simulation.',
  'When to trade': 'Restrict new entries by session, weekday and the available high-impact-news calendar. Hours use UTC with local-time context. Compared playbooks retain their own session windows.',
  'Costs': 'Enable commission, spread and slippage to model execution friction. Commission is charged per side and slippage can affect both sides; units depend on the selected contract. Turning costs off changes the simulated result.',
  'Prop-firm challenge': 'Test against the displayed challenge limits, such as profit target, drawdown, daily loss and minimum days. Templates are editable simulation assumptions; verify the actual program rules separately before using them as a benchmark.',
  'Risk per trade': 'Select percentage of current simulated balance, a fixed money risk or a fixed quantity. Stop distance and contract valuation connect risk to size. Check the units and amount before running or entering a practice position.',
  'Stop loss': 'The price or rule intended to exit an adverse move. In practice and backtests, fills follow the chosen bar and execution assumptions; a stop level is not a guarantee of an exact real-world fill.',
  'Take profit': 'The price or reward multiple used to exit a favorable move. Simulated outcomes depend on whether the available bars reach it and how the engine resolves stop/target events in the same bar.',
  'Order price': 'The simulated entry price for the selected order type. A pending order waits for the replay’s price conditions; a market order uses the engine’s current fill convention and configured costs.',
  'Risk': 'The intended loss budget for this simulated entry. Review the sizing mode, initial stop distance and contract units together; fixed quantity and percentage risk do not produce the same exposure.',
  'Breakeven at R (optional)': 'When the simulated trade reaches this multiple of initial risk, the supported management rule moves its stop to the entry level. Costs and execution assumptions can still leave a negative net result at that price.',
  'Result': 'Limit the displayed trade or practice records to their labeled outcome. This is a view filter; it does not change recorded fills or strategy rules. Unknown outcomes remain distinct from losses.',
  'R from': 'Lower bound for the realized R filter. R measures outcome relative to initial risk. Use the paired upper-bound control for a range; records with unknown R cannot establish a value inside that range.',
  'Exit reason': 'Filter simulated trades by the engine’s recorded closing event, such as stop, target or time exit. The label describes the modeled event and may not capture a discretionary real-world decision.',
  'Weekday': 'Filter the recorded entry weekday for the table’s labeled timezone. This narrows the displayed evidence rather than changing the underlying simulated run.',
  'Hold time from (min)': 'Minimum entry-to-exit duration in minutes for this table filter. Use the paired upper limit to isolate a duration range; missing or invalid exit times cannot support a known holding period.',
  'Demo equity (USD)': 'Starting account-value assumption for the demo sizing monitor. It determines the money risk implied by a percentage budget; it is not a connected broker balance.',
  'Position sizing': 'Choose how practice quantity is derived: fixed units or an available risk-based method. Inspect stop distance, equity and contract valuation because the same quantity can mean different money risk across instruments.',
  'Risk budget per entry (%)': 'Intended percentage of demo equity to risk on one entry. The monitor uses available stop and valuation assumptions to translate this into size; missing contract data limits precision.',
  'Scenario setup': 'Choose the saved hypothesis whose direction and price levels supply context for this position test. Inspect the imported values; selecting a scenario does not establish that its trigger occurred.',
  'Demo bar size': 'The duration represented by each displayed demo candle. Changing it changes the visible price aggregation and the opportunities the simulation can observe.',
  'Hypothesis stop (ATR)': 'Stop distance expressed as a multiple of the available Average True Range estimate. ATR describes recent price movement, not a fixed money risk; quantity and contract value still determine the loss budget.',
  'Hypothesis target (R)': 'Target distance measured as a multiple of the initial stop risk. A target of 2R aims for twice that risk before the model’s trading costs; reaching it depends on the simulated price path.',
  'Commission ($/unit/side)': 'Demo commission in dollars per quantity unit for each entry or exit side. A complete round trip incurs both sides; verify whether the source quantity represents shares, lots, coins or contracts.',
  'Equity scope': 'Choose which trade cohort contributes to the comparison curve. This can differ from the single trade highlighted on the candle chart, so inspect the scope and counts beside the curve.',
  'Chart view': 'Switch between the available candle and result-curve presentations of the same study. Each view answers a different question: execution context or accumulated outcomes.',
  'Rank by training result': 'Choose the metric used to rank parameter candidates on the earlier training sample. Later-period results remain a separate check, so changing the ranking metric does not create new independent evidence.',
  'Trade history benchmark': 'Select the recorded trades that serve as the actual baseline. Journal scope and the study’s date, instrument and playbook filters constrain the cohort. Imported history is evidence for comparison, rather than a new automated entry strategy.',
  'Playbook setup': 'Use a saved setup to prefill compatible scenario and execution context. Inspect which written conditions have a supported automated equivalent; transferring a playbook does not make all prose executable.',
  'Playbook scenario': 'Choose an optional saved trade hypothesis to supply planned direction, entry, stop and target. Missing fields remain evidence gaps rather than becoming actual historical fills.',
  'From entry date': 'Inclusive lower bound on the source trades’ recorded entry dates. This narrows the comparison cohort, rather than selecting trades by their exit dates.',
  'To entry date': 'Inclusive upper bound on the source trades’ recorded entry dates. Check it alongside the lower bound and the overall journal scope to understand the available sample.',
  'Choose a trade benchmark': 'Choose an individual recorded trade for a detailed comparison of the baseline and alternatives. Inspect source currency, costs, unit valuation and candle coverage before comparing money results.',
  'Actual vs saved scenario': 'Compare the recorded baseline with a previously saved What-if study. The saved rule and evidence define the alternative; differences can reflect removed trades or modeled exits rather than improved real executions.',
  'Saved scenario equity': 'Cumulative recorded-baseline and hypothetical results for the selected saved study. This is a comparison of study outcomes; it does not reconstruct live broker equity.',
  'Your setup vs MarketSyde AI': 'Compares your selected setup with the local recommendation under the displayed data and valuation assumptions. Inspect entry, exit, costs and sample coverage to understand why the paths differ.',
  'Trade history vs position test vs MarketSyde AI': 'Three distinct views: the recorded journal result, an editable position simulation, and a local suggested alternative. The latter two use the displayed candle and execution assumptions and do not replace actual trading history.',
  'Edit selected playbook setups': 'Change supported setup parameters for the selected comparison candidates. Edits affect the scenario being tested; inspect the resulting rules before saving or transferring an experiment.',
  'Replay log': 'Review the recorded setup alongside the available generated price comparison and optional attached recording. The comparison is not an authenticated broker tick history; availability and valuation assumptions are shown inside the replay.',
  'Before emotion': 'Record how you felt before entry, using your own recollection or contemporaneous notes. This supports later emotion/process comparisons; leave unanswered when you cannot establish it reliably.',
  'After emotion': 'Record how you felt after the trade, separately from the before-entry answer. The journal uses these answers to help you review patterns; it does not infer them from P&L.',
  'Profitable days': 'Days with a positive eligible trading result divided by days with any eligible result, including flat days. Grouping uses recorded UTC entry date and the selected gross or net basis.',
  'Daily net drawdown': 'Largest decline of cumulative daily eligible net results below their previous peak, starting at zero for this selected cohort. Days are grouped by recorded entry date. Open P&L and intraday equity swings are not included.',
  'Max risk per trade': 'Your maximum planned percentage of account equity to risk on an entry. The journal monitor leaves this check Unknown when the required risk/equity history is unavailable; the value alone cannot prove compliance.',
  'Max daily loss': 'Your intended maximum daily loss as a percentage of account equity. The journal needs suitable equity and loss-history evidence to assess it; setting the rule does not block real broker orders.',
  'Stop after consecutive losses': 'Your intended limit on consecutive eligible losing trades before stopping for the day. The monitor needs complete timing and result evidence to check whether another entry followed that sequence.',
  'Live': 'Statistics from eligible recorded journal trades linked to this playbook. These reflect the current journal scope and its known costs and R evidence, rather than a continuously connected broker feed.',
  'Tested': 'Statistics from the backtest saved as this playbook’s expected result. Its dates, instrument, risk and cost assumptions can differ from the live journal sample; compare coverage before interpreting a gap.',
};

