export function getJournalHelp(label: string): string | undefined {
  return JOURNAL_HELP[aliases[label] || label];
}

export function JournalHelp({ label, text }: { label: string; text?: string }) {
  const description = text || getJournalHelp(label);
  return description ? <InfoTooltip label={label} description={description} /> : null;
}
